-- Durable denial identities have no foreign keys to deletable business rows.
CREATE TABLE media_tombstones (
 kind TEXT NOT NULL CHECK(kind IN ('asset','observation','face_instance','event')),
 object_id TEXT NOT NULL,
 scope_id TEXT NOT NULL,
 deletion_id TEXT NOT NULL,
 generation INTEGER NOT NULL,
 created_at TEXT NOT NULL,
 PRIMARY KEY(kind, object_id)
);
CREATE INDEX idx_media_tombstone_scope ON media_tombstones(scope_id,kind);
INSERT INTO media_tombstones SELECT 'asset',m.asset_id,d.scope_id,d.deletion_id,m.generation,d.created_at
 FROM media_deletion_members m JOIN media_deletions d ON d.deletion_id=m.deletion_id;
INSERT INTO media_tombstones SELECT 'observation',o.id,o.scope_id,d.deletion_id,m.generation,d.created_at
 FROM observations o JOIN media_deletion_members m ON m.asset_id=o.asset_id JOIN media_deletions d ON d.deletion_id=m.deletion_id;
INSERT INTO media_tombstones SELECT 'face_instance',f.id,a.scope_id,d.deletion_id,m.generation,d.created_at
 FROM face_instances f JOIN assets a ON a.id=f.asset_id JOIN media_deletion_members m ON m.asset_id=f.asset_id JOIN media_deletions d ON d.deletion_id=m.deletion_id;
CREATE TRIGGER media_tombstone_immutable_update BEFORE UPDATE ON media_tombstones BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_tombstone_immutable_delete BEFORE DELETE ON media_tombstones BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
CREATE TRIGGER media_member_tombstones AFTER INSERT ON media_deletion_members BEGIN
 INSERT OR IGNORE INTO media_tombstones SELECT 'asset',a.id,a.scope_id,NEW.deletion_id,NEW.generation,d.created_at
 FROM assets a JOIN media_deletions d ON d.deletion_id=NEW.deletion_id WHERE a.id=NEW.asset_id;
 INSERT OR IGNORE INTO media_tombstones SELECT 'observation',o.id,o.scope_id,NEW.deletion_id,NEW.generation,d.created_at
 FROM observations o JOIN media_deletions d ON d.deletion_id=NEW.deletion_id WHERE o.asset_id=NEW.asset_id;
 INSERT OR IGNORE INTO media_tombstones SELECT 'face_instance',f.id,a.scope_id,NEW.deletion_id,NEW.generation,d.created_at
 FROM face_instances f JOIN assets a ON a.id=f.asset_id JOIN media_deletions d ON d.deletion_id=NEW.deletion_id WHERE f.asset_id=NEW.asset_id;
END;
CREATE TABLE media_deletion_plans (
 plan_id TEXT PRIMARY KEY,
 deletion_id TEXT NOT NULL REFERENCES media_deletions(deletion_id),
 version INTEGER NOT NULL,
 fingerprint TEXT NOT NULL,
 created_at TEXT NOT NULL,
 source_versions_json TEXT NOT NULL,
 payload_json TEXT NOT NULL,
 UNIQUE(deletion_id, fingerprint),
 UNIQUE(deletion_id, version)
);
CREATE TRIGGER media_plan_immutable_update BEFORE UPDATE ON media_deletion_plans BEGIN SELECT RAISE(ABORT,'immutable_deletion_plan'); END;
CREATE TRIGGER media_plan_immutable_delete BEFORE DELETE ON media_deletion_plans BEGIN SELECT RAISE(ABORT,'immutable_deletion_plan'); END;
CREATE TRIGGER tombstone_assets_insert_1 BEFORE INSERT ON assets WHEN (EXISTS (SELECT 1 FROM media_tombstones t WHERE t.kind='asset' AND t.object_id=NEW.id) OR EXISTS (SELECT 1 FROM media_tombstones t WHERE t.kind='asset' AND t.object_id=NEW.parent_asset_id)) BEGIN SELECT RAISE(ABORT,'media_isolated'); END;
