DROP VIEW readable_assets;
CREATE VIEW readable_assets AS SELECT * FROM assets a WHERE a.deletion_state='active'
 AND NOT EXISTS (SELECT 1 FROM media_tombstones t WHERE t.kind='asset' AND t.object_id=a.id);
DROP VIEW readable_events;
CREATE VIEW readable_events AS SELECT e.* FROM events e WHERE
 NOT EXISTS (SELECT 1 FROM media_tombstones t WHERE (t.kind='event' AND t.object_id=e.id) OR (t.kind='asset' AND t.object_id=e.source_asset_id))
 AND NOT EXISTS (SELECT 1 FROM event_observations eo JOIN media_tombstones t ON t.kind='observation' AND t.object_id=eo.observation_id WHERE eo.event_id=e.id);
DROP VIEW readable_memory_vectors;
CREATE VIEW readable_memory_vectors AS SELECT v.* FROM memory_vectors v WHERE NOT EXISTS (
 SELECT 1 FROM media_tombstones t WHERE (t.kind=v.source_type AND t.object_id=v.source_id)
 OR (t.kind='asset' AND t.object_id=json_extract(v.metadata_json,'$.asset_id'))
 OR (t.kind='observation' AND t.object_id=json_extract(v.metadata_json,'$.observation_id')))
 AND NOT (v.source_type='event' AND EXISTS (SELECT 1 FROM events WHERE id=v.source_id) AND NOT EXISTS (SELECT 1 FROM readable_events WHERE id=v.source_id));
DROP VIEW readable_text_vectors;
CREATE VIEW readable_text_vectors AS SELECT v.* FROM text_vectors v WHERE NOT EXISTS (
 SELECT 1 FROM media_tombstones t WHERE (t.kind=v.source_type AND t.object_id=v.source_id)
 OR (t.kind='asset' AND t.object_id=json_extract(v.metadata_json,'$.asset_id'))
 OR (t.kind='observation' AND t.object_id=json_extract(v.metadata_json,'$.observation_id')))
 AND NOT (v.source_type='event' AND EXISTS (SELECT 1 FROM events WHERE id=v.source_id) AND NOT EXISTS (SELECT 1 FROM readable_events WHERE id=v.source_id));
DROP VIEW readable_facts;
CREATE VIEW readable_facts AS SELECT x.* FROM facts x WHERE NOT EXISTS (
 SELECT 1 FROM json_each(x.evidence_ids_json) j JOIN media_tombstones t ON t.kind=CASE WHEN j.type='object' THEN json_extract(j.value,'$.kind') ELSE 'observation' END AND t.object_id=CASE WHEN j.type='object' THEN json_extract(j.value,'$.id') ELSE j.value END);
DROP VIEW readable_relationships;
CREATE VIEW readable_relationships AS SELECT x.* FROM relationships x WHERE NOT EXISTS (
